fix:
Always route read-your-writes requests to the single source of truth (the primary database being written to) during the migration phase, or track a write timestamp/version vector to block reading until the target catches up [192, 659].
```rust
async fn save_and_get_user_fixed(db: &LegacyDB, _migration_target: &NewDB, user_id: u64, email: String) -> Result<User, Error> {
    db.write(user_id, &email).await?;
    let user = db.read_user(user_id).await?; // Read from source of truth
    Ok(user)
}
